    {
      "evidence_id": "S1",
      "en": "The ThrottleWithOpts function expects the backlogLimit to be positive.",
      "pt-br": "A função ThrottleWithOpts espera que o backlogLimit seja positivo."
    },
    {
      "evidence_id": "S2",
      "en": "The setRetryAfterHeaderIfNeeded method sets the Retry-After header value to 0 if the delay is negative.",
      "pt-br": "A função setRetryAfterHeaderIfNeeded define o valor do header Retry-After como 0 se o delay for negativo."
